begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
insert into auth.users(id) values('02000000-0000-4000-8000-000000000001');
insert into public.tenants(id,name,demo) values('12000000-0000-4000-8000-000000000001','Live simulation blocked',false);
insert into public.sites(id,tenant_id,name) values('22000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','Test site');
insert into public.memberships(tenant_id,site_id,user_id,role,capabilities) values('12000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','02000000-0000-4000-8000-000000000001','STAFF',array['parking.configure','parking.simulate']);
insert into public.parking_zones(id,tenant_id,site_id,name,capacity) values('32000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','Counter',10);
insert into public.iot_devices(id,tenant_id,site_id,zone_id) values('42000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','32000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claim.sub','02000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.simulate_parking('42000000-0000-4000-8000-000000000001',2)$$,'42501','Forbidden','simulation server-disabled outside demo tenant');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),0,2,now())$$,'42501',null,'browser cannot bypass signed bridge');
set local role service_role;
select lives_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001',0,2,now())$$,'valid counter event');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),0,3,now())$$,'P0001','Invalid or replayed event','duplicate sequence denied');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001',1,3,now())$$,'23505',null,'event UUID replay denied');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),1,11,now())$$,'P0001','Invalid or replayed event','overcapacity denied');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),1,3,now()-interval '3 minutes')$$,'P0001','Invalid or replayed event','old observation denied');
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),1,3,now()+interval '1 minute')$$,'P0001','Invalid or replayed event','future observation denied');
reset role;
update public.iot_devices set active=false;
set local role service_role;
select throws_ok($$select public.ingest_parking('42000000-0000-4000-8000-000000000001',gen_random_uuid(),1,3,now())$$,'P0001','Device unavailable','suspended device rejected');
reset role;
update public.iot_events set created_at=now()-interval '8 days';
select private.retain();
select is((select count(*)::int from public.iot_events),0,'old device events retained only seven days');
select * from finish();
rollback;
